// Üretilen dosya: tool/ozgun/uret.py. Tarih · Osmanlı Devleti: kuruluştan dağılmaya olaylar, kurumlar, kişiler (zor).
const ozHistory3Zor = <(String, String, List<String>, String)>[
  ('Orhan Bey döneminde İznik\'te ilk Osmanlı medresesinin açılması devletin hangi yönde geliştiğini gösterir?', 'Beylikten yerleşik bir devlet düzenine geçişi', ['Göçebe yaşam tarzının güçlendirilmesini', 'Bizans\'la her alanda tamamen barışçı ilişkiler kurulmasını', 'Merkezî yönetimin zayıflatılmasını'], 'Medrese açılması, kadı ve müderris yetiştirme ihtiyacının doğduğunu ve devletin kurumsallaştığını gösterir.'),
  ('I. Murad\'ın Anadolu\'da Germiyanoğulları ile evlilik, Hamitoğulları ile satın alma yoluyla toprak kazanması neyi göstermektedir?', 'Anadolu\'da Türk beyliklerine karşı barışçı yöntemlerin öncelendiğini', ['Anadolu\'da yalnız savaşla genişleme politikası izlendiğini', 'Osmanlıların Anadolu\'dan tamamen çekildiğini', 'Bizans\'ın Anadolu\'da güçlendiğini'], 'Kütahya ve çevresi çeyiz, bazı Hamitoğlu toprakları ise satın alma yoluyla alındı; bu Anadolu\'da barışçı genişlemenin örneğidir.'),
  ('Fetret Devri\'nin Osmanlı\'yı yıkıma götürmeyip yaklaşık on yılda sona ermesinde aşağıdakilerden hangisinin payı en büyüktür?', 'Taşradaki tımar ve yönetim düzeninin büyük ölçüde işlemeye devam etmesi', ['Timur\'un Osmanlı topraklarını doğrudan yönetmesi', 'Bizans\'ın Osmanlı şehzadelerinden birini tahta çıkarması', 'Anadolu\'daki bütün Türk beyliklerinin Osmanlı\'ya gönüllü olarak katılıp asker vermesi'], 'Merkezde iktidar boşluğu olmasına karşın yerleşik tımar ve idare düzeni ile Rumeli\'deki Türk nüfusu devletin dağılmasını önledi.'),
  ('Fetret Devri\'nde Çelebi Mehmed\'e karşı ortaya çıkan ve Bizans\'ın desteklediği, Bayezid\'in oğlu olduğunu iddia eden şehzade kimdir?', 'Düzmece Mustafa', ['Cem Sultan', 'Şehzade Bayezid Çelebi', 'Şehzade Korkut'], 'Mustafa Çelebi (Düzmece Mustafa), Bizans\'ın desteğiyle Çelebi Mehmed\'e ve sonra II. Murad\'a karşı taht mücadelesine girişti.'),
  ('1444 Edirne-Segedin Antlaşması\'nın ardından II. Murad\'ın tahtı oğluna bırakması hangi gelişmeye yol açmıştır?', 'Haçlıların antlaşmayı bozup saldırıya geçmesine', ['Bizans\'ın İstanbul\'u savaşsız biçimde Osmanlı\'ya teslim etmesine', 'Karamanoğullarının Osmanlı\'ya katılmasına', 'Yeniçeri Ocağı\'nın kaldırılmasına'], 'Genç II. Mehmed\'in tahta çıkmasını fırsat bilen Haçlılar antlaşmayı bozdu; II. Murad yeniden orduya geçerek Varna\'da zafer kazandı.'),
  ('II. Murad döneminde Oğuz kültürüne ilgi gösterilmesi, Türkçe eserlerin yazdırılması ve paralara Kayı boyu damgasının basılması hangi amaca yöneliktir?', 'Osmanlı\'nın Türk kimliğini ve hanedan meşruiyetini güçlendirmek', ['Bizans saray kültürünü ve törenlerini Osmanlı sarayında yaygınlaştırmak', 'Arapçayı resmî dil hâline getirmek', 'Memlüklerle siyasi birlik kurmak'], 'Timur sonrası dönemde Oğuz soyuna vurgu, hanedanın Türk dünyasında meşruiyetini artırmayı amaçlıyordu.'),
  ('İstanbul\'un fethinin Avrupa tarihinde Orta Çağ\'ın sonu sayılmasının dayandığı gerekçelerden biri hangisidir?', 'Topun surları aşmada etkili olması ve feodal şatoların korunma işlevinin sarsılması', ['Avrupa\'da matbaanın ilk kez bu olaydan hemen sonra icat edilip kullanılmaya başlanması', 'Papalığın tüm siyasi gücünü bu tarihte kaybetmesi', 'Coğrafi Keşiflerin bu olayla tamamen sona ermesi'], 'Kuşatmada topun etkin kullanımı derebeylik kalelerinin savunma değerini düşürmüş ve dönüm noktası olarak kabul edilmiştir.'),
  ('Fatih döneminde İtalya\'da Otranto\'yu ele geçirerek Roma\'yı tedirgin eden Osmanlı komutanı kimdir?', 'Gedik Ahmed Paşa', ['Mahmud Paşa', 'Hadım Süleyman Paşa', 'Zağanos Paşa'], 'Gedik Ahmed Paşa 1480\'de Otranto\'yu aldı; Fatih\'in ölümü üzerine bu üs elden çıktı.'),
  ('Fatih\'in \'Kayser-i Rum\' unvanını kullanması ve kendini Roma\'nın vârisi olarak görmesi hangi siyasi düşünceyi yansıtır?', 'Cihan hâkimiyeti ülküsünü ve evrensel imparatorluk iddiasını', ['Yalnız Anadolu ile sınırlı kalan bir uç beyliği anlayışını ve yerel yönetimi', 'Bizans\'a bağlı bir tekfur olma kabulünü', 'Halifeliğin Mısır\'da kalması gerektiği görüşünü'], 'İstanbul\'u alan Fatih, Doğu Roma\'nın mirasçısı sıfatıyla evrensel bir imparatorluk tasavvuru geliştirmiştir.'),
  ('Fatih\'in Venedik\'le 1463-1479 yılları arasında yaptığı uzun savaşın sonunda imzalanan barışla ilgili hangisi doğrudur?', 'Venedik yıllık vergi ödeyerek Osmanlı\'da ticaret hakkını sürdürdü', ['Venedik İstanbul\'daki tüm ticari haklarını kalıcı olarak kaybetti', 'Osmanlı, Mora\'yı Venedik\'e bıraktı', 'Osmanlı, Venedik\'e kapitülasyon vermeyi reddetti ve ilişki kesildi'], '1479 barışıyla Venedik yıllık vergi ödemeyi kabul etti, karşılığında ticaret ayrıcalıklarını korudu.'),
  ('Cem Sultan\'ın Avrupalıların elinde bulunduğu yıllarda Osmanlı dış politikasının temkinli kalmasının başlıca nedeni neydi?', 'Cem\'in bir Haçlı seferinde koz olarak kullanılması kaygısı', ['Osmanlı donanmasının Akdeniz\'de tamamen yok olması ve yeniden kurulamaması', 'Safevilerin İstanbul\'u kuşatmış olması', 'Yeniçerilerin savaşmayı reddetmesi'], 'Avrupalılar Cem\'i tahta aday göstererek bir Haçlı hareketi düzenleyebilirdi; II. Bayezid bu nedenle Batı\'ya karşı büyük seferlerden kaçındı.'),
  ('Turnadağ Savaşı (1515) sonucunda Osmanlı\'ya bağlanan beylik hangisidir?', 'Dulkadiroğulları', ['Ramazanoğulları Beyliği', 'Karamanoğulları', 'Candaroğulları'], 'Turnadağ\'da Dulkadir Beyi Alaüddevle yenildi ve beylik Osmanlı topraklarına katıldı.'),
  ('I. Viyana Kuşatması\'nın başarısız olmasında coğrafi uzaklık ve iklim koşullarının belirleyici olması, Osmanlı ordusunun hangi yapısal sınırını gösterir?', 'Sefer mevsimi kısa olduğundan uzak hedeflerde etkinliğin azalmasını', ['Osmanlı ordusunda hiç ateşli silah ve top bulunmamasını', 'Yeniçerilerin kuşatma savaşına katılamamasını', 'Osmanlı\'nın donanma kuramamasını'], 'İstanbul\'dan yola çıkan ordu Viyana\'ya geç ulaşıyor, kış bastırmadan dönmek zorunda kalıyordu; bu durum \'menzil\' sınırı olarak yorumlanır.'),
  ('1533\'te Osmanlı ile Avusturya arasında imzalanan ve Avusturya arşidükünün protokolde Osmanlı sadrazamına denk sayıldığı antlaşma hangisidir?', 'İstanbul Antlaşması', ['Zitvatorok Antlaşması', 'Karlofça Antlaşması', 'Edirne Antlaşması'], '1533 İstanbul Antlaşması\'yla Ferdinand protokolde sadrazama eşit kabul edildi; bu Osmanlı üstünlüğünün göstergesiydi.'),
  ('1536\'da Fransa\'ya verilen ayrıcalıkların Kanuni\'nin dış politikasındaki işlevi en iyi hangi seçenekle açıklanır?', 'Habsburglara karşı Avrupa\'daki birliği bozmak ve Fransa\'yı güçlendirmek', ['Fransa\'nın Osmanlı\'ya vergi ödemesini sağlamak', 'Osmanlı\'nın Fransız ordusuna katılmasını kolaylaştırmak', 'Fransız Katolik misyonerlerini İstanbul\'dan ve Kudüs\'ten tamamen uzaklaştırmak'], 'Habsburglar karşısında Fransa\'yı desteklemek Avrupa\'da Hristiyan birliğinin kurulmasını engellemeyi amaçlıyordu.'),
  ('1560\'ta İspanyol öncülüğündeki Haçlı donanmasının Osmanlı\'ya yenildiği deniz savaşı hangisidir?', 'Cerbe Deniz Savaşı', ['Preveze Deniz Savaşı', 'İnebahtı Deniz Savaşı', 'Navarin Deniz Savaşı'], 'Cerbe\'de Piyale Paşa ve Turgut Reis komutasındaki Osmanlı donanması İspanyol-Haçlı donanmasını yendi.'),
  ('Osmanlı\'da donanma komutanı ve Kapudan Paşa\'nın yönettiği deniz üssü ile tersane işleri hangi kurum etrafında örgütlenmişti?', 'Tersane-i Âmire', ['Tophane-i Âmire', 'Darphane-i Âmire', 'Matbaa-i Âmire'], 'İstanbul Kasımpaşa\'daki Tersane-i Âmire, gemi yapımı ve donanma işlerinin merkeziydi.'),
  ('Osmanlı\'nın 1569\'da Don ve Volga nehirlerini birleştirecek bir kanal açmayı planlaması hangi amaca yönelikti?', 'Orta Asya\'ya ulaşmak ve Rus ilerleyişini durdurmak', ['Akdeniz\'i Kızıldeniz\'e bağlamak', 'Venedik ticaretini Akdeniz\'den Karadeniz limanlarına çekmek', 'Avusturya\'yı arkadan kuşatmak'], 'Don-Volga Kanalı projesi, Hazar yoluyla Orta Asya Türkleriyle bağlantı kurmayı ve Astrahan\'a inen Rusları durdurmayı hedefliyordu.'),
  ('Osmanlı\'nın 16. yüzyılda Portekizlilere karşı yardım istemesi üzerine Endonezya\'daki hangi Müslüman sultanlığa top ve uzman göndermişti?', 'Açe Sultanlığı', ['Delhi Sultanlığı', 'Gucerat Sultanlığı', 'Zengibar Sultanlığı'], 'Sumatra\'daki Açe Sultanlığı\'nın yardım talebi üzerine Kanuni ve II. Selim döneminde top ve topçu ustaları gönderildi.'),
  ('İnebahtı yenilgisinden sonra donanmanın kısa sürede yeniden kurulup Tunus\'un 1574\'te alınması neyi göstermektedir?', 'Devletin hâlâ büyük mali ve teknik kaynaklara sahip olduğunu', ['Haçlıların İnebahtı\'da da yenildiğini', 'Osmanlı\'nın bu yenilgiden sonra Akdeniz\'den tamamen çekildiğini ve kıyılarını koruyamadığını', 'Venedik\'in Osmanlı\'ya donanma bağışladığını'], 'Yaklaşık bir yıl içinde yeni bir donanmanın yapılması, devletin kaynaklarının hâlâ çok güçlü olduğunu kanıtlar.'),
  ('Celali isyanlarının uzun vadede yol açtığı \'Büyük Kaçgun\' olgusu hangi sonucu doğurmuştur?', 'Köylülerin toprağı terk etmesiyle üretimin ve vergi gelirinin düşmesi', ['Anadolu nüfusunun kısa sürede ikiye katlanması', 'Tımar sisteminin yeniden güçlenmesi', 'Balkanlar\'dan Anadolu\'ya doğru Müslüman nüfusun büyük bir göç dalgası başlatması'], 'Köylüler güvenli yerlere ve şehirlere kaçtı; birçok köy boşaldı, üretim ve vergi geliri düştü.'),
  ('Zitvatorok Antlaşması\'nın Osmanlı\'nın Batı karşısındaki üstünlüğü açısından anlamı nedir?', 'Osmanlı siyasi üstünlüğünün sarsıldığının ilk işareti olması', ['Osmanlı\'nın ilk kez toprak kaybettiği antlaşma olması', 'Kapitülasyonların ilk kez kaldırıldığı antlaşma olması', 'Osmanlı\'nın Avusturya\'yı vergiye bağladığı ilk antlaşma olması'], 'Toprak kaybı olmasa da Avusturya\'nın eşit sayılması, Osmanlı\'nın Avrupa\'daki siyasi üstünlüğünün gerilemeye başladığını gösterir.'),
  ('1672 Bucaş Antlaşması\'nın Osmanlı tarihindeki yeri hangisidir?', 'Osmanlı\'nın Avrupa\'da en geniş sınırlarına ulaşması', ['Osmanlı\'nın ilk kez toprak kaybettiği antlaşma olması', 'Rusya ile yapılan ilk antlaşma olması', 'Kapitülasyonların sürekli hâle getirildiği antlaşma olması'], 'Lehistan\'la imzalanan Bucaş Antlaşması\'yla Podolya alındı; Osmanlı Avrupa\'da en geniş sınırlarına ulaştı.'),
  ('Köprülüler döneminin başarıları kalıcı bir yenileşmeye dönüşememiştir. Bunun temel nedeni hangisidir?', 'Başarıların kurumlara değil, kişilerin otoritesine dayanması', ['Köprülülerin hiçbir seferde başarı kazanamaması', 'Padişahların Köprülülere hiç yetki vermemesi', 'Osmanlı\'nın bu dönemde tüm komşularıyla tamamen barış içinde olup ordusunu dağıtması'], 'Köprülü ıslahatları sadrazamların kişisel otoritesine bağlıydı; bu kişiler gidince düzen yeniden bozuldu.'),
  ('Karlofça Antlaşması ile hangi devlete hangi toprak bırakılmıştır?', 'Venedik\'e Mora ve Dalmaçya kıyıları', ['Rusya\'ya Kırım ve Kafkasya', 'Fransa\'ya Mısır ve Suriye', 'İngiltere\'ye Kıbrıs ve Malta adaları ile Rodos'], 'Karlofça\'da Venedik Mora\'yı, Avusturya Macaristan\'ın büyük kısmını, Lehistan Podolya\'yı aldı; Rusya ile ayrı olarak 1700\'de İstanbul Antlaşması yapıldı.'),
  ('Karlofça görüşmelerinde Osmanlı\'nın ilk kez arabulucuları (İngiltere ve Hollanda) kabul etmesi ne anlama gelir?', 'Osmanlı\'nın Avrupa diplomasisine pazarlık eden bir taraf olarak girmesi', ['Osmanlı\'nın Avrupa\'yı tümüyle egemenliği altına alıp kendi koşullarını tek taraflı dayatması', 'Osmanlı\'nın diplomatik ilişkileri tamamen kesmesi', 'Osmanlı\'nın İngiltere\'nin himayesine girmesi'], 'Önceki dönemlerde koşulları tek taraflı belirleyen Osmanlı, artık masada pazarlık eden ve arabulucuya ihtiyaç duyan bir taraf olmuştu.'),
  ('Lale Devri\'ni sona erdiren 1730 Patrona Halil İsyanı\'nın arka planında hangi etkenin bulunduğu kabul edilir?', 'Saraydaki lüks yaşama ve İran\'daki kayıplara duyulan tepki', ['Matbaada Kur\'an basılmasına karşı ulemanın silahlı ayaklanması', 'Yeniçeri Ocağı\'nın kaldırılmasına duyulan öfke', 'Tanzimat Fermanı\'nın gayrimüslimlere tanıdığı haklar'], 'Halkın ekonomik sıkıntısı, saray çevresindeki eğlence ve israf algısı ile İran\'daki kayıplar isyanın zeminini hazırladı.'),
  ('1739 Belgrad Antlaşması\'nın ardından Fransa\'ya 1740\'ta kapitülasyonların sürekli hâle getirilmesinin uzun vadeli etkisi hangisidir?', 'Ayrıcalıkların padişah değişince yenilenmeden kalıcılaşması', ['Fransa\'nın bu ayrıcalıklar karşılığında Osmanlı\'ya her yıl vergi ödemeye başlaması', 'Osmanlı\'nın Fransa\'dan toprak kazanması', 'Kapitülasyonların bütün devletler için yasaklanması'], 'Önceden padişahın kişisel lütfu sayılan kapitülasyonlar 1740\'ta süreklilik kazandı; bu durum ekonomik bağımlılığı artırdı.'),
  ('Küçük Kaynarca Antlaşması\'nın Rusya\'ya Osmanlı\'daki Ortodoks tebaanın haklarını gözetme fırsatı tanıması ilerleyen dönemde hangi sonuca yol açmıştır?', 'Rusya\'nın Osmanlı iç işlerine karışmasına dayanak oluşturmasına', ['Osmanlı\'nın Ortodoks kilisesini kapatmasına', 'Rusya\'nın Osmanlı\'ya vergi ödemesine', 'Osmanlı ile Rusya\'nın Avrupa\'ya karşı uzun süreli ve kalıcı bir ittifak kurmasına'], 'Bu madde 19. yüzyılda Rusya\'nın Balkan uluslarını kışkırtması ve Kırım Savaşı\'na giden süreçte bir müdahale gerekçesi olarak kullanıldı.'),
  ('Sened-i İttifak\'ın merkeziyetçi yapıya ters düştüğü ileri sürülür. Bunun gerekçesi hangisidir?', 'Ayanların varlığını ve yerel güçlerini resmen tanıması', ['Padişahın tüm yetkilerini halka devretmesi', 'Yeniçeri ağalarını Divan\'a üye yapıp devlet yönetimine ortak etmesi', 'Gayrimüslimlere ayrı bir meclis kurması'], 'Belgeyle ayanların toprak ve yönetim hakları güvenceye alındı; bu durum merkezî otoriteyi zayıflatan bir yön taşıyordu.'),
  ('Alemdar Mustafa Paşa\'nın kurduğu ve Nizam-ı Cedid\'in devamı niteliğindeki askerî birlik hangisidir?', 'Sekban-ı Cedid', ['Asakir-i Mansure', 'Redif Taburları', 'Hamidiye Alayları'], 'Sekban-ı Cedid, Alemdar\'ın 1808\'de kurduğu yeni ordudur; yeniçeri ayaklanmasında Alemdar ölünce dağıtıldı.'),
  ('II. Mahmud\'un ayanların gücünü kırmaya yönelik politikası ile Sened-i İttifak\'ı imzalamış olması birlikte değerlendirildiğinde hangi sonuca varılabilir?', 'Padişahın belgeyi zorla imzalayıp fırsat bulunca merkezî otoriteyi güçlendirdiği', ['Padişahın ayanlara karşı her zaman yumuşak bir politika izlediği', 'Sened-i İttifak\'ın II. Mahmud\'un kendi fikri olduğu', 'Ayanların II. Mahmud döneminde güçlenerek devlete egemen olduğu'], 'II. Mahmud, Alemdar\'ın baskısıyla imzaladığı belgeyi uygulamadı ve ayanları tek tek tasfiye ederek merkezî otoriteyi güçlendirdi.'),
  ('Rusya ile imzalanan ve Sırplara ilk kez bazı imtiyazlar tanınmasını öngören 1812 tarihli antlaşma hangisidir?', 'Bükreş Antlaşması', ['Edirne Antlaşması', 'Yaş Antlaşması', 'Ziştovi Antlaşması'], 'Bükreş Antlaşması\'yla Sırplara bazı imtiyazlar verildi; bu, ilerideki Sırp özerkliğinin ilk adımı oldu.'),
  ('Navarin Baskını\'nın Yunan sorunu açısından belirleyici olmasının nedeni hangisidir?', 'Osmanlı\'nın denizden Mora\'ya asker ve ikmal ulaştıramaması', ['Osmanlı\'nın bu baskından sonra Yunan isyancılarla ittifak yapıp Rusya\'ya savaş açması', 'Rusya\'nın Osmanlı\'ya katılması', 'İngiltere\'nin Mora\'yı ilhak etmesi'], 'Donanmasını kaybeden Osmanlı, Mora\'daki kuvvetlerini destekleyemez hâle geldi ve Yunan bağımsızlığı kaçınılmaz oldu.'),
  ('Mehmed Ali Paşa sorununun Osmanlı\'nın iç meselesi olmaktan çıkıp uluslararası bir soruna dönüşmesinin nedeni nedir?', 'Boğazlar ve Doğu Akdeniz\'deki çıkarlar yüzünden büyük devletlerin müdahalesi', ['Mısır\'ın ilk kez Osmanlı\'ya katılmış olması', 'Osmanlı\'nın sorunu çözmek için İran\'dan ve Afganistan\'dan askerî yardım istemesi', 'Mehmed Ali Paşa\'nın Avrupa\'da toprak talep etmesi'], 'İngiltere, Fransa ve Rusya; Boğazlar, Hindistan yolu ve Akdeniz\'deki çıkarları nedeniyle soruna doğrudan müdahil oldu.'),
  ('Hünkâr İskelesi Antlaşması\'ndan sonra İngiltere\'nin Osmanlı\'ya 1838\'de Balta Limanı Ticaret Antlaşması\'nı imzalatması nasıl yorumlanabilir?', 'İngiltere\'nin siyasi desteğe karşılık ekonomik ayrıcalık alması', ['İngiltere\'nin Osmanlı sanayisini korumak istemesi', 'Osmanlı\'nın İngiltere\'yi ekonomik olarak denetim altına alması', 'Osmanlı\'nın tüm gümrük gelirlerini artırması'], 'Mısır sorununda İngiliz desteğine ihtiyaç duyan Osmanlı, Balta Limanı ile İngiliz tüccarlarına geniş ticari kolaylıklar tanıdı.'),
  ('Kapitülasyonların yükselme döneminde Osmanlı için sorun yaratmaması ama sonraki yüzyıllarda zararlı hâle gelmesi nasıl açıklanabilir?', 'Güçlü devletin lütfu olan ayrıcalıklar zayıflayınca müdahale aracına dönüştü', ['Kapitülasyonlar başlangıçta yalnız Osmanlı tüccarlarına ve esnaf loncalarına verilmişti', 'İlk kapitülasyonlarda Avrupalıların vergi ödememesi şartı yoktu', 'Sonraki yüzyıllarda kapitülasyonlar tümüyle kaldırılmıştı'], 'Güçlü Osmanlı ayrıcalıkları istediği zaman geri alabilirdi; zayıflayınca bunlar Avrupa devletlerinin hakkı gibi kullanılmaya başlandı.'),
  ('Tanzimat Fermanı\'nın ilanında Mısır sorununda Avrupa\'nın desteğini kazanma isteğinin etkili olduğu söylenir. Bu yorum fermanın hangi özelliğini öne çıkarır?', 'Dış baskı ve diplomatik ihtiyaçlarla şekillenmesini', ['Halkın ayaklanmasıyla zorla kabul ettirilmesini', 'Yalnız askerî alanda düzenleme getirmesini', 'Ulemanın isteğiyle hazırlanmasını'], 'Ferman, Mısır krizinde Avrupa\'nın desteğini almak ve iç işlere müdahaleyi önlemek kaygısı da taşıyordu.'),
  ('Ahmed Cevdet Paşa başkanlığındaki bir komisyon tarafından hazırlanan ve İslam hukukunun borçlar ve medeni hukuka ilişkin kurallarını madde madde düzenleyen eser hangisidir?', 'Mecelle-i Ahkâm-ı Adliye', ['Kanunname-i Âl-i Osman', 'Multeka\'l-Ebhur', 'Düstur-ı Belediye'], 'Mecelle (1869-1876), Hanefi fıkhına dayalı medeni hukuk kurallarını kanun maddeleri hâlinde derledi.'),
  ('Kırım Savaşı\'nı Osmanlı kazanan taraf olarak bitirdiği hâlde antlaşmadan beklediği kazancı sağlayamadığı söylenir. Bunun en önemli gerekçesi hangisidir?', 'Toprak kazanamaması ve iç işlerine Avrupa müdahalesinin yolunun açılması', ['Savaşta Rusya\'ya toprak kaybetmesi', 'Antlaşmayla kapitülasyonların genişletilmesi ve tüm Avrupa devletlerine uygulanması', 'Osmanlı\'nın Kırım\'ı Rusya\'ya bırakması'], 'Osmanlı toprak kazanmadı, ağır borca girdi ve Islahat Fermanı Paris Antlaşması\'nda anılarak Avrupa\'nın denetimine açıldı.'),
  ('Islahat Fermanı\'nın Paris Konferansı öncesinde ilan edilmesinin amacı en iyi hangi seçenekle açıklanır?', 'Avrupa\'nın gayrimüslimler bahanesiyle müdahalesini önlemek', ['Rusya ile yeni bir savaşı başlatmak', 'Kapitülasyonları tümüyle kaldırmak', 'Osmanlı\'yı Avrupa diplomasisinden tamamen yalıtıp Rusya ile ittifak kurmak'], 'Osmanlı, hakları kendiliğinden tanıyarak konferansta müdahale konusunun açılmasının önüne geçmek istedi; ancak ferman antlaşmada anıldı.'),
  ('Kanun-i Esasi\'de padişaha sakıncalı gördüğü kişileri sürgüne gönderme yetkisi veren 113. madde, meşrutiyetin niteliği hakkında neyi gösterir?', 'Padişahın yetkilerinin geniş ölçüde korunduğunu', ['Halk egemenliğinin tam olarak sağlandığını', 'Meclisin padişahı görevden alabildiğini', 'Anayasanın padişahı tamamen etkisiz kılıp sembolik bir makama indirdiğini'], 'Bu madde, anayasaya rağmen padişahın güçlü konumunu koruduğunu gösterir; Midhat Paşa da bu maddeye dayanılarak sürgün edildi.'),
  ('Berlin Antlaşması\'yla bağımsızlıkları tanınan devletler hangileridir?', 'Sırbistan, Karadağ ve Romanya', ['Yunanistan, Bulgaristan ve Arnavutluk', 'Bulgaristan, Bosna ve Hersek', 'Mısır, Tunus ve Cezayir'], 'Berlin\'de Sırbistan, Karadağ ve Romanya bağımsız oldu; Bulgaristan ise özerk prenslik olarak kaldı.'),
  ('Berlin Antlaşması\'nda Doğu Anadolu\'da Ermenilerin yaşadığı yerlerde ıslahat yapılmasının kararlaştırılması ilerleyen dönemde hangi soruna kaynaklık etmiştir?', 'Ermeni meselesinin uluslararası bir sorun hâline gelmesine', ['Kürt beyliklerinin bağımsız olmasına', 'Rusya\'nın Doğu Anadolu\'dan tamamen çekilmesine', 'Osmanlı\'nın İran\'la savaşmasına'], 'Ermeni meselesi ilk kez uluslararası bir antlaşmada yer aldı ve büyük devletlerin müdahale gerekçesi oldu.'),
  ('Hicaz Demiryolu\'nun büyük ölçüde iç bağışlarla yapılması, II. Abdülhamid\'in hangi politikasının bir yansımasıdır?', 'İslamcılık politikası ile dünya Müslümanlarının desteğini kazanma', ['Batıcılık politikası ile Avrupa sermayesini ülkeye çekme', 'Türkçülük politikası ile Orta Asya\'ya ulaşma', 'Osmanlıcılık politikası ile gayrimüslimleri kazanma'], 'Hicaz Demiryolu hem hac yolculuğunu kolaylaştırdı hem de halifelik etrafında İslam birliği düşüncesini güçlendirdi.'),
  ('II. Abdülhamid döneminde tütün tekelini işletme hakkı yabancı ortaklı bir şirkete verilmiştir. Bu şirketin adı nedir?', 'Reji Şirketi', ['Lloyd Şirketi', 'Doğu Hindistan Şirketi', 'Levant Şirketi'], 'Tütün tekeli 1883\'te Reji Şirketi\'ne verildi; şirketin uygulamaları kaçakçılık ve çatışmalara yol açtı.'),
  ('1909 Kanun-i Esasi değişiklikleriyle getirilen yenilik hangisidir?', 'Padişahın yetkileri azaltıldı, meclisinki artırıldı', ['Padişaha meclisi istediği zaman kapatma ve mebusları sürgün etme yetkisi ilk kez verildi', 'Meclis-i Âyan kaldırılarak tek meclisli yapıya geçildi', 'Halifelik makamı kaldırıldı'], '1909 değişikliğiyle hükûmet meclise karşı sorumlu hâle geldi ve padişahın yetkileri kısıtlandı; parlamenter sisteme geçildi.'),
  ('II. Meşrutiyet döneminde ilk kez çok partili hayata geçilmiş olması ile Bab-ı Âli Baskını\'nın ardından tek parti yönetiminin kurulması birlikte değerlendirildiğinde ne söylenebilir?', 'Kurumların kurulduğu ama demokratik kültürün yerleşmediği', ['Osmanlı\'nın 1908\'den itibaren yeniden tamamen mutlakiyete döndüğü ve meclisin kapandığı', 'Çok partili yaşamın hiç denenmediği', 'Meclisin bu dönemde hiç toplanmadığı'], 'Partiler ve seçimler gerçekleşti ancak darbe ve baskılarla tek parti yönetimine geçilmesi demokratik kültürün zayıf kaldığını gösterir.'),
  ('Uşi Antlaşması\'yla Oniki Ada\'nın İtalya\'da kalması hangi koşula bağlanmıştı?', 'Geçici olarak, Osmanlı askerlerinin Libya\'dan çekilmesine kadar', ['Kalıcı olarak, İtalya\'nın Libya\'dan çekilmesi şartıyla', 'Yunanistan\'a satılmak üzere', 'Osmanlı\'nın savaş tazminatı ödemesi şartıyla'], 'Antlaşmaya göre adalar Libya\'daki Osmanlı askerleri çekilince iade edilecekti; ancak Balkan Savaşı\'nın patlak vermesiyle İtalya adaları elinde tuttu.'),
  ('Balkan Savaşları\'ndan sonra Osmanlıcılık fikrinin büyük ölçüde etkisini yitirmesi hangi gelişmeyle doğrudan ilişkilidir?', 'Farklı unsurların ayrılıkçı milliyetçiliğinin sürmesi', ['Osmanlı\'nın Balkanlar\'da yeni topraklar kazanıp nüfusunu artırması', 'Halifeliğin bu savaşlarla kaldırılması', 'Osmanlı\'nın İngiltere ile ittifak kurması'], 'Balkan Savaşları birlik fikrinin işlemediğini gösterdi; Arnavutların da ayrılması üzerine Türkçülük güç kazandı.'),
  ('Irak Cephesi\'nde 1916\'da İngiliz General Townshend\'in ordusuyla birlikte esir alındığı yer hangisidir?', 'Kûtü\'l-Amâre', ['Bağdat', 'Basra', 'Musul'], 'Halil (Kut) Paşa komutasındaki kuvvetler Kûtü\'l-Amâre\'de Townshend\'i teslim aldı.'),
  ('1916\'da İngilizlerin desteğiyle Osmanlı\'ya karşı isyan eden Mekke Emiri kimdir?', 'Şerif Hüseyin', ['Şerif Ali Haydar', 'İbn Suud', 'Faysal bin Abdülaziz'], 'Şerif Hüseyin 1916\'da İngilizlerin teşvikiyle Hicaz\'da Osmanlı\'ya isyan etti.'),
  ('Fatih döneminden itibaren padişahın divan toplantılarına başkanlık etmeyi bırakıp kafes arkasından izlemesi hangi gelişmeyle ilişkilendirilir?', 'Sadrazamın yetki ve sorumluluğunun artması', ['Divanın tamamen kaldırılması', 'Şeyhülislamın divanı yönetmeye başlaması', 'Divan üyelerinin seçimle belirlenmesi'], 'Padişahın divana katılmaması, sadrazamın divanı onun adına yöneten mutlak vekil konumunu güçlendirdi.'),
  ('Enderun\'da liyakate dayalı bir eğitim sistemi uygulanmasının devlet yönetimine katkısı nedir?', 'Soy yerine yeteneğe göre yetişen yöneticiler sağlaması', ['Soylu Türkmen ailelerinin kuşaklar boyunca devlete egemen olmasını sağlaması', 'Yöneticilerin seçimle iş başına gelmesini sağlaması', 'Taşra yönetimini ayanlara bırakması'], 'Enderun\'da başarı gösterenler yükselir, sadrazamlığa kadar çıkabilirdi; bu padişaha bağlı, aristokrasi dışı bir yönetici sınıfı oluşturdu.'),
  ('Enderun\'daki odalardan biri olan ve padişahın özel hizmetini gören en itibarlı oda hangisidir?', 'Has Oda', ['Büyük Oda', 'Küçük Oda', 'Seferli Odası'], 'Has Oda, padişahın kişisel hizmetiyle görevli en seçkin odaydı; başında Has Odabaşı bulunurdu.'),
  ('Topkapı Sarayı\'nın düzeninde Birun, Enderun ve Harem\'in ayrı avlular etrafında kademeli olarak yerleşmesi hangi yönetim anlayışını yansıtır?', 'Padişaha ulaşmanın belirli kurallara ve hiyerarşiye bağlı olmasını', ['Sarayın halka tamamen açık olmasını', 'Saray görevlilerinin tümünün eşit yetki ve rütbeye sahip olmasını', 'Sarayın yalnız bir askerî üs olarak kullanılmasını'], 'Dıştan içe doğru ilerleyen avlular, padişaha yakınlığın hiyerarşik ve törensel bir düzenle sınırlandığını gösterir.'),
  ('Kırım Hanlığı, Eflak ve Boğdan gibi bölgelerin Osmanlı yönetimindeki statüsü nasıl tanımlanır?', 'İç işlerinde serbest, vergi ve asker veren bağlı yönetimler', ['Doğrudan merkezden atanan beylerbeylerince yönetilen salyaneli eyaletler', 'Tımar sisteminin en yoğun uygulandığı eyaletler', 'Hiçbir yükümlülüğü olmayan bağımsız devletler'], 'Bu bölgeler yerli hanedanlarca yönetilir, Osmanlı\'ya vergi verir ve gerektiğinde asker gönderirdi; iç işlerinde serbesttiler.'),
  ('Tanzimat sonrasında 1864 Vilayet Nizamnamesi ile eyaletlerin yerine vilayetlerin kurulması hangi amaca yönelikti?', 'Taşra yönetimini modernleştirip merkeze daha sıkı bağlamak', ['Taşrada tımar sistemini yeniden kurmak', 'Vilayetleri kendi meclisleri olan bağımsız devletlere dönüştürmek', 'Taşradaki kadılık kurumunu güçlendirmek'], 'Vilayet sistemi Fransız modelinden etkilenerek taşra yönetimini kademeli ve merkeziyetçi bir yapıya kavuşturdu.'),
  ('Tımar sisteminin devlete sağladığı yararlardan hangisi ekonomik nitelikte değildir?', 'Taşrada asayişin sağlanması', ['Hazineden para çıkmadan büyük bir ordunun beslenmesi', 'Tarımsal üretimin sürekliliğinin korunması', 'Vergilerin yerinde toplanması'], 'Asayişin sağlanması siyasi-idari bir yarardır; diğer seçenekler ekonomik yararlardır.'),
  ('Kapıkulu Ordusu\'nda yeniçerilerin silah ve cephanesini yapan, taşıyan ve onaran birliklere ne ad verilirdi?', 'Cebeci', ['Topçu', 'Top arabacı', 'Lağımcı'], 'Cebeciler silah ve cephanenin yapımı, bakımı ve taşınmasından sorumluydu.'),
  ('Osmanlı ordusunda tımarlı sipahilerin sayıca kapıkulu askerlerinden çok olmasına rağmen yeniçerilerin önemli bir siyasi güç hâline gelmesinin nedeni hangisidir?', 'Başkentte toplu hâlde bulunmaları', ['Taşrada geniş toprakların sahibi olmaları', 'Seçimle göreve gelmeleri', 'Ulemadan oluşmaları'], 'Yeniçeriler İstanbul\'da toplu hâlde bulunduğu için saray ve hükûmet üzerinde doğrudan baskı kurabiliyorlardı.'),
  ('Gelirleri bir kalenin muhafızlarına ya da ordunun belirli ihtiyaçlarına ayrılan miri arazilere ne ad verilirdi?', 'Ocaklık', ['Paşmaklık', 'Yurtluk', 'Mukataa'], 'Ocaklık, gelirleri kale muhafızları, tersane, top dökümü gibi askerî ihtiyaçlara ayrılan topraklardı.'),
  ('Gelirleri padişahın kızlarına, hanımlarına ve annesine ayrılan miri arazilere ne ad verilirdi?', 'Paşmaklık', ['Ocaklık', 'Yurtluk', 'Has'], 'Paşmaklık (başmaklık) arazilerinin gelirleri saray kadınlarının harcamalarına ayrılırdı.'),
  ('Osmanlı\'da gayrimüslimlerin kendi aralarındaki evlenme, boşanma ve miras gibi işleri kendi dinî mahkemelerinde görmeleri hangi anlayışın sonucudur?', 'Millet sistemindeki hukuki özerkliğin', ['Kapitülasyonların yalnız yabancı tüccarlara tanıdığı ayrıcalıkların', 'Tanzimat\'la getirilen laik hukukun', 'Kadıların gayrimüslim olmasının'], 'Millet sistemi gayrimüslim toplulukların aile ve kişi hukukunu kendi dinî kurallarına göre çözmesine izin verirdi.'),
  ('Osmanlı\'da bir kişinin kadı ya da müderris olarak yükselmesini düzenleyen, mezunların atama sırası beklemesi usulüne ne ad verilirdi?', 'Mülazemet', ['Mukataa', 'Müsadere', 'İltizam'], 'Medreseden mezun olanlar atanmak için mülazım olarak kaydedilir ve sıraları gelince göreve başlardı.'),
  ('1695\'te uygulanmaya başlanan malikane sistemi iltizamdan hangi yönüyle ayrılır?', 'Vergi toplama hakkının ömür boyu verilmesi', ['Vergi toplama hakkının yalnız askerlere verilmesi', 'Vergilerin tamamen kaldırılması', 'Vergilerin yalnız ayni olarak toplanması'], 'Malikane sisteminde vergi kaynağı peşin bir bedel karşılığı ömür boyu verilirdi; amaç vergi kaynağının korunmasıydı.'),
  ('1775\'te uygulanmaya başlanan ve vergi gelirlerinin hisselere bölünerek halka satılmasına dayanan iç borçlanma yöntemi hangisidir?', 'Esham', ['Kaime', 'Malikane', 'Mukataa'], 'Esham, belirli vergi gelirlerinin hisse senetlerine bölünüp satılmasıyla oluşturulan bir iç borçlanma aracıydı.'),
  ('Lonca sisteminin 18. ve 19. yüzyıllarda Osmanlı sanayisinin gelişmesini zorlaştırdığı ileri sürülür. Bunun en güçlü gerekçesi hangisidir?', 'Rekabeti ve üretim artışını sınırlayan katı kurallar', ['Loncaların devletten tamamen bağımsız olması', 'Loncaların yabancı tüccarlarca yönetilmesi', 'Loncaların para basma yetkisine sahip olması'], 'Sabit fiyat, sınırlı üye ve geleneksel üretim yöntemleri yeniliği ve sermaye birikimini engelleyerek Avrupa\'nın makine üretimi karşısında güçsüz bıraktı.'),
  ('16. yüzyılın sonlarında Amerika\'dan Avrupa\'ya akan ucuz gümüşün etkisiyle Osmanlı\'da yaşanan durum hangisidir?', 'Akçenin değer kaybetmesi ve fiyatların yükselmesi', ['Osmanlı\'nın büyük bir ekonomik zenginleşme yaşaması', 'Gümüş paranın tamamen yasaklanması', 'Esnafın gelirlerinin artması'], 'Gümüş bolluğu Osmanlı parasının değerini düşürdü; 1585-86\'daki tağşiş enflasyonu artırdı ve sabit gelirlileri, özellikle yeniçerileri etkiledi.'),
  ('Osmanlı\'da tımar sahibi köylüden öşür ve çift resmi gibi vergileri toplarken, cizye gibi bazı vergilerin doğrudan merkez hazinesine ait olması neyi göstermektedir?', 'Vergi gelirlerinin merkez ile taşra arasında paylaştırıldığını', ['Bütün vergilerin tımar sahiplerine ait olduğunu', 'Merkezin taşradan hiç gelir almadığını', 'Cizyenin yalnız tımarlı sipahilerce toplandığını'], 'Tımar sistemi tüm gelirleri taşraya bırakmıyordu; bazı vergiler merkez hazinesi adına ayrıca toplanırdı.'),
  ('Millet sisteminin 19. yüzyılda milliyetçilik akımlarıyla birlikte devleti zorlaması nasıl açıklanabilir?', 'Kendi dinî kurumları olan toplulukların bunları ulusal kimliğe dönüştürebilmesi', ['Millet sisteminin tüm toplulukları tek bir dilde birleştirmiş olması', 'Gayrimüslimlerin hiçbir dinî kuruma sahip olmaması', 'Millet sisteminin 16. yüzyılda kaldırılmış olması'], 'Kendi kiliseleri, okulları ve mahkemeleri olan topluluklar, milliyetçilik fikirleri yayılınca bu kurumları ayrılıkçı hareketlerin merkezine dönüştürebildi.'),
  ('Tanzimat ve Islahat fermanlarıyla Müslüman ve gayrimüslimlerin hukuken eşit sayılması, millet sistemini nasıl etkilemiştir?', 'Dine dayalı ayrımı zayıflatıp ortak vatandaşlığı öne çıkarmıştır', ['Millet sistemini güçlendirerek her etnik grup için ayrı yeni milletler oluşturmuştur', 'Gayrimüslimlerin vergilerini artırmıştır', 'Müslümanların haklarını kaldırmıştır'], 'Eşitlik ilkesi, dine dayalı statü farklılıklarını azaltarak Osmanlı vatandaşlığı anlayışını geliştirmeye yöneldi.'),
  ('1868\'de açılan Galatasaray Mekteb-i Sultanisi\'nin Osmanlı eğitim tarihindeki önemi hangisidir?', 'Farklı dinlerden öğrencilerin Fransızca eğitim gördüğü bir lise olması', ['Yalnız Müslüman öğrencilerin kabul edildiği ilk medrese olması', 'Osmanlı\'nın ilk kız okulu olması', 'Yalnız askerî eğitim veren bir okul olması'], 'Galatasaray Sultanisi, Osmanlıcılık anlayışıyla farklı milletlerden öğrencileri bir araya getiren, Fransızca eğitim veren bir okuldu.'),
  ('19. yüzyılda yabancı ve azınlık okullarının Osmanlı\'da hızla artması devletin hangi kaygısını beslemiştir?', 'Bu okulların ayrılıkçı fikirleri yaymasından duyulan kaygıyı', ['Bu okulların öğrenci bulamamasından duyulan kaygıyı', 'Bu okulların yalnız Türkçe eğitim verip azınlık dillerini yasaklamasından duyulan kaygıyı', 'Bu okulların vergi ödememesinden doğan bütçe açığını'], 'Misyoner ve azınlık okulları milliyetçi düşüncelerin yayılmasına aracılık ediyor, bu da II. Abdülhamid döneminde devlet okullarının artırılmasına yol açıyordu.'),
  ('Kâtip Çelebi\'nin Mizanü\'l-Hak adlı eserinde tartışmalı konularda ılımlı bir yol önermesi, onun düşünce yapısıyla ilgili neyi gösterir?', 'Akli bilimlere önem verip aşırılıklardan uzak durmayı savunduğunu', ['Bütün bilimleri reddettiğini', 'Yalnız askerî konulara ilgi duyduğunu', 'Batı\'yı her alanda taklit etmeyi önerdiğini'], 'Kâtip Çelebi, Kadızadeliler-Sivasiler tartışmalarında ılımlı bir tutum alarak akli bilimlerin ihmal edilmemesi gerektiğini savundu.'),
  ('Osmanlı tarihini 1591-1660 arası için kaleme alan ve ilk resmî vakanüvis kabul edilen tarihçi kimdir?', 'Naima', ['Âşıkpaşazade', 'Peçevi', 'Ahmed Cevdet Paşa'], 'Mustafa Naima\'nın Tarih-i Naima\'sı ilk resmî vakanüvis tarihi olarak kabul edilir.'),
  ('18. yüzyılda yapılan Nuruosmaniye Camii\'nde barok ve rokoko unsurların görülmesi neyi gösterir?', 'Osmanlı mimarisinde Batı etkisinin başladığını', ['Osmanlı\'nın Batı\'yı tamamen reddettiğini', 'Klasik üslubun hiç değişmeden sürdüğünü', 'Camilerin yalnız Avrupalı mimarlarca yapıldığını'], 'Nuruosmaniye Camii, Osmanlı barok üslubunun en tanınmış örneklerindendir ve Batı etkisinin mimariye yansımasıdır.'),
  ('Bursa\'daki Yeşil Cami ve Ulu Cami gibi erken dönem yapılarından Süleymaniye\'ye uzanan süreçte Osmanlı cami mimarisindeki genel eğilim nedir?', 'Merkezî ve tek büyük kubbeli mekân anlayışının gelişmesi', ['Kubbe kullanımının tamamen terk edilmesi', 'Minarelerin yapılmamaya başlanması', 'Ahşap yapıların tercih edilmesi'], 'Çok kubbeli ve bölünmüş planlardan, büyük merkezî kubbe altında bütünleşen tek mekâna doğru bir gelişim görülür.'),
  ('1840\'ta İngiliz William Churchill tarafından çıkarılan ve yarı resmî nitelik taşıyan Türkçe gazete hangisidir?', 'Ceride-i Havadis', ['Tercüman-ı Ahval', 'Takvim-i Vekayi', 'Tasvir-i Efkâr'], 'Ceride-i Havadis, devletten destek gören yarı resmî bir gazeteydi.'),
  ('19. yüzyılda gazetelerin yaygınlaşması Osmanlı siyasi hayatında nasıl bir etki yaratmıştır?', 'Kamuoyunun oluşmasına ve muhalif fikirlerin yayılmasına', ['Halkın devlet işlerine ilgisinin tamamen yok olup siyasetten uzaklaşmasına', 'Saray dışında yazı yazılmasının yasaklanmasına', 'Medreselerin sayısının artmasına'], 'Gazeteler, meşrutiyet ve hürriyet gibi fikirleri geniş kitlelere ulaştırarak kamuoyunun doğmasını sağladı.'),
  ('Prens Sabahattin\'in savunduğu \'teşebbüs-i şahsi ve adem-i merkeziyet\' görüşünün temel önerisi hangisidir?', 'Bireysel girişimin ve yerinden yönetimin uygulanması', ['Merkezî yönetimin güçlendirilmesi ve özel girişimin yasaklanması', 'Halifeliğin güçlendirilip İslam birliğinin kurulması', 'Bütün Türklerin tek bir devlet çatısında birleşmesi'], 'Prens Sabahattin, kişisel girişimciliği ve taşraya geniş yetki tanıyan yerinden yönetimi savunuyordu.'),
  ('Balkan Savaşları\'nda Müslüman Arnavutların da Osmanlı\'dan ayrılması hangi fikir akımının etkisini en çok azaltmıştır?', 'Osmanlıcılık ve İslamcılık', ['Yalnız Türkçülük', 'Yalnız Batıcılık', 'Adem-i merkeziyetçilik'], 'Gayrimüslimlerin ayrılması Osmanlıcılığı, Müslüman Arnavutların ayrılması ise İslamcılığı zayıflattı; bu durum Türkçülüğü güçlendirdi.'),
  ('Osmanlıcılık fikrinin Tanzimat ve Islahat fermanlarıyla ilişkisi en iyi hangi ifadeyle açıklanır?', 'Fermanların eşitlik ilkesi Osmanlıcılığa zemin hazırlamıştır', ['Fermanlar Osmanlıcılığı yasaklamıştır', 'Fermanlar yalnız Türkçülüğü desteklemiştir', 'Osmanlıcılık bu fermanlardan çok önce, Lale Devri\'nde terk edilmiştir'], 'Tebaanın din farkı gözetmeksizin eşit olması, ortak Osmanlı kimliği fikrine hukuki zemin hazırladı.'),
  ('Şehzadelerin sancağa çıkarılması uygulamasının kaldırılıp sarayda \'kafes\' denilen bölümde tutulmaları hangi sonucu doğurmuştur?', 'Tahta deneyimsiz padişahların çıkması', ['Taht kavgalarının artması', 'Şehzadelerin ordu komutanı olması', 'Padişahların çok genç yaşta tahta çıkması'], 'Sarayda yaşayan şehzadeler yönetim ve askerî deneyim kazanamadan tahta geçti; bu da devlet yönetimini olumsuz etkiledi.'),
  ('Kanuni Sultan Süleyman döneminde Şehzade Bayezid ile Şehzade Selim arasında yaşanan mücadele nasıl sonuçlanmıştır?', 'Bayezid yenilip İran\'a sığındı ve sonra öldürüldü', ['Bayezid tahta çıkıp Selim\'i Kırım\'a sürgün etti ve hanlık verdi', 'İki şehzade barışıp ülkeyi paylaştı', 'Selim, Bayezid\'i affedip vezir yaptı'], '1559 Konya Savaşı\'nda yenilen Bayezid, Safevilere sığındı; 1561\'de teslim edilerek öldürüldü.'),
  ('Osmanlıların Balkanlar\'da yerli Hristiyan halka ağır vergi yükü getirmeyip mevcut düzeni büyük ölçüde korumasını ifade eden yönetim anlayışına ne ad verilir ve bu anlayışın sonucu ne olmuştur?', 'İstimalet politikası; fethedilen halkın Osmanlı yönetimini benimsemesi', ['Müsadere politikası; yerli halkın topraklarını ve mallarını kaybetmesi', 'Devşirme politikası; yerli halkın topluca göç etmesi', 'İltizam politikası; vergilerin artması'], 'İstimalet, gönül alma siyasetidir; adil vergi ve din serbestliği, Balkan halkının Osmanlı\'ya bağlanmasını kolaylaştırdı.'),
  ('Karamanoğullarının Osmanlı\'ya karşı sık sık Haçlılar, Venedik ve Akkoyunlularla iş birliği yapması, Osmanlı\'nın Balkan politikalarını nasıl etkilemiştir?', 'Osmanlı\'yı aynı anda iki cephede savaşma riskine karşı temkinli davranmaya zorlamıştır', ['Osmanlı\'nın Balkanlar\'dan tamamen çekilmesine yol açmıştır', 'Osmanlı\'nın Karamanoğulları ile kalıcı ve eşit bir ittifak kurup Balkanlar\'ı paylaşmasını sağlamıştır', 'Osmanlı\'nın Haçlılarla ortak donanma kurmasını sağlamıştır'], 'Karaman tehdidi nedeniyle Osmanlı, Rumeli\'de savaşırken Anadolu\'yu korumak zorunda kalıyordu; Varna öncesindeki Karaman seferi buna örnektir.'),
  ('1541\'de Kanuni döneminde doğrudan Osmanlı eyaleti hâline getirilen Macar şehri hangisidir?', 'Budin', ['Belgrad', 'Temeşvar', 'Zigetvar'], '1541\'de Budin alınarak Budin Beylerbeyliği kuruldu; Orta Macaristan doğrudan Osmanlı yönetimine girdi.'),
  ('Kanuni döneminde Osmanlı\'nın Fas ve Hindistan\'daki Müslüman devletlerle ilişki kurması ve Portekiz\'e karşı yardım göndermesi hangi rolüyle açıklanabilir?', 'Halifelik makamının getirdiği İslam dünyasını koruma sorumluluğuyla', ['Kapitülasyonların Müslüman devletlere de verilip ticaretin genişletilmesiyle', 'Bu devletlerin Osmanlı eyaleti olmasıyla', 'Osmanlı\'nın Avrupa\'dan tamamen çekilmesiyle'], 'Hilafetin Osmanlı\'ya geçmesinden sonra Osmanlı, uzak Müslüman topluluklara yardım etmeyi siyasi ve dinî bir görev olarak gördü.'),
  ('III. Mehmed\'in sefere bizzat katıldığı ve Avusturya-Macar ordusunun yenildiği 1596 tarihli meydan savaşı hangisidir?', 'Haçova Meydan Muharebesi', ['Mohaç Meydan Muharebesi', 'Zenta Muharebesi', 'Petervaradin Muharebesi'], 'Haçova\'da kazanılan zaferle Eğri kalesi alındı; bu savaş Uzun Savaşlar\'ın önemli zaferlerindendir.'),
  ('Merzifonlu Kara Mustafa Paşa\'nın Viyana kuşatmasında hücuma geç karar vermesinin şehrin düşmemesindeki etkisi en iyi hangi seçenekle açıklanır?', 'Kuşatmanın uzaması yardım ordusunun gelmesine zaman kazandırdı', ['Osmanlı ordusu şehre girdikten sonra kendi isteğiyle geri çekildi', 'Kuşatma bir antlaşmayla erkenden sona erdi', 'Viyanalılar şehri boşaltıp Osmanlı\'ya teslim etti'], 'Uzayan kuşatma sırasında Leh Kralı Sobieski komutasındaki yardım ordusu Kahlenberg\'e ulaştı ve Osmanlı ordusunu bozguna uğrattı.'),
  ('Osmanlı\'nın 1715\'te Mora\'yı Venedik\'ten geri alması Pasarofça Antlaşması\'nda nasıl sonuçlanmıştır?', 'Mora Osmanlı\'da kaldı, Belgrad Avusturya\'ya geçti', ['Mora yeniden Venedik\'e verildi', 'Osmanlı hem Mora\'yı hem de Belgrad\'ı koruyarak savaştan kazançlı çıktı', 'Mora bağımsız bir devlet oldu'], 'Pasarofça\'da Osmanlı Mora\'yı korudu fakat Avusturya\'ya karşı kayıplar verdi; Belgrad elden çıktı.'),
  ('1908\'de II. Meşrutiyet\'in ilanından kısa süre sonra yaşanan gelişmelerden hangisi Osmanlı\'nın toprak kaybıyla ilgilidir?', 'Bosna-Hersek\'in ilhakı ve Bulgaristan\'ın bağımsızlığı', ['Mısır\'ın Osmanlı\'ya yeniden bağlanması', 'Kıbrıs\'ın Osmanlı\'ya geri verilmesi', 'Osmanlı\'nın Girit\'i ilk kez fethetmesi'], 'Meşrutiyetin karışıklığından yararlanan Avusturya Bosna-Hersek\'i ilhak etti, Bulgaristan bağımsızlığını ilan etti, Girit de Yunanistan\'a bağlandığını açıkladı.'),
  ('Rusya\'nın 19. yüzyılda Balkan Slavlarını desteklemesinin altında yatan iki temel politika hangileridir?', 'Panslavizm ve sıcak denizlere inme', ['Panislamizm ve Pantürkizm', 'Liberalizm ve sosyalizm', 'Merkantilizm ve kapitalizm'], 'Rusya, Slavları tek çatı altında toplama (Panslavizm) ve Boğazlar yoluyla sıcak denizlere ulaşma amacıyla Balkanlar\'a müdahale ediyordu.'),
  ('Tanzimat döneminde Mustafa Reşid Paşa\'nın öğrencisi olarak yetişen ve uzun yıllar sadrazamlık ile hariciye nazırlığı yapan iki devlet adamı kimlerdir?', 'Âli Paşa ve Fuad Paşa', ['Midhat Paşa ve Mahmud Nedim Paşa', 'Talat Paşa ve Enver Paşa', 'Said Paşa ve Kâmil Paşa'], 'Âli ve Fuad Paşalar, Tanzimat\'ın ikinci kuşak önderleri olarak 1850-1870\'li yıllarda yönetime damgasını vurdu.'),
  ('Tepedelenli Ali Paşa\'nın üzerine ordu gönderilmesinin Yunan isyanının büyümesini kolaylaştırdığı söylenir. Bu yorumun dayanağı hangisidir?', 'Kuvvetler Yanya\'dayken Mora\'nın savunmasız kalması', ['Tepedelenli\'nin Yunan isyancılarca Yunanistan kralı ilan edilmesi', 'Osmanlı\'nın Yunanlılarla ittifak kurması', 'Rusya\'nın Tepedelenli\'yi desteklemesi'], 'Kuvvetlerin Yanya\'ya yoğunlaşması, 1821\'de Mora\'da başlayan isyanın ilk aşamada hızla yayılmasına fırsat verdi.'),
  ('1746 Kerden Antlaşması\'nın Osmanlı-İran ilişkilerindeki yeri hangisidir?', 'Sınırın Kasr-ı Şirin\'deki gibi korunması', ['İran\'ın Osmanlı\'ya bağlanması', 'Osmanlı\'nın Bağdat\'ı İran\'a bırakması', 'Osmanlı\'nın Kafkasya\'nın tamamını alması'], 'Nadir Şah ile yapılan Kerden Antlaşması\'yla sınır, Kasr-ı Şirin\'de belirlenen çizgiye göre korundu.'),
  ('18. yüzyılda Osmanlı\'nın İngiltere, Fransa gibi devletlerin arabuluculuğunu sık sık kabul etmesi ne anlama gelmektedir?', 'Osmanlı\'nın dengeleri kullanarak varlığını korumaya çalıştığını', ['Osmanlı\'nın bütün savaşları kazandığını', 'Osmanlı\'nın Avrupa\'dan tamamen koptuğunu', 'Osmanlı\'nın bu devletlere bağlandığını'], 'Askerî gücü azalan Osmanlı, Avrupa\'daki güç dengesini kullanarak diplomasiye ağırlık verdi.'),
  ('Aşağıdaki antlaşmalardan hangisi Karlofça ile Pasarofça antlaşmaları arasındaki dönemde imzalanmıştır?', 'Prut Antlaşması', ['Belgrad Antlaşması', 'Küçük Kaynarca Antlaşması', 'Zitvatorok Antlaşması'], 'Karlofça 1699, Pasarofça 1718 tarihlidir; Prut 1711\'de imzalandı. Zitvatorok 1606, Belgrad 1739, Küçük Kaynarca 1774 tarihlidir.'),
  ('\'Tanzimat Fermanı tamamen Avrupa\'nın baskısıyla ilan edilmiştir.\' yargısına yöneltilebilecek en güçlü itiraz hangisidir?', 'Fermandan önce de III. Selim ve II. Mahmud\'un yenilik yapmış olması', ['Fermanın Gülhane\'de okunmuş olması', 'Fermanın Hariciye Nazırı Mustafa Reşid Paşa tarafından halkın önünde okunması', 'Fermanın 1839\'da ilan edilmesi'], 'Islahat çabalarının daha önceden sürüyor olması, fermanın yalnız dış baskıyla açıklanamayacağını gösterir.'),
  ('\'Lale Devri yalnız bir eğlence ve israf dönemidir.\' görüşünü en çok zayıflatan bilgi hangisidir?', 'Bu dönemde matbaanın kurulup tercüme heyetinin çalışması', ['Bu dönemde lale yetiştiriciliğinin ve soğan ticaretinin İstanbul\'da yaygınlaşması', 'Bu dönemde Sadabad Köşkü\'nün yapılması', 'Bu dönemin Patrona Halil İsyanı\'yla sona ermesi'], 'Matbaa, tercüme heyeti, kâğıt ve kumaş atölyeleri gibi yenilikler dönemin yalnız eğlenceyle açıklanamayacağını gösterir.'),
  ('Bir öğrenci \'Osmanlı\'da ıslahatlar hep askerî alanla sınırlı kalmıştır.\' diyor. Aşağıdakilerden hangisi bu görüşün yanlış olduğunu gösterir?', 'Tanzimat\'la hukuk ve yönetimde düzenlemeler yapılması', ['Nizam-ı Cedid ordusunun kurulması', 'Asakir-i Mansure-i Muhammediye ordusunun kurulup eğitilmesi', 'Mühendishanelerin açılması'], 'Tanzimat, can-mal güvenliği, yargı ve vergi düzeni gibi askerî olmayan alanlarda da düzenleme getirdi.'),
  ('19. yüzyılda Osmanlı\'nın Avrupa\'dan aldığı borçların sorunlu hâle gelmesinde en belirleyici etken hangisidir?', 'Borçların yatırıma değil, bütçe açıklarına harcanması', ['Borçların yalnız eğitime harcanması', 'Borç veren devletlerin faiz almaması', 'Osmanlı\'nın aldığı borçların tamamını kısa sürede ve faiziyle birlikte ödemesi'], 'Borçlar sanayi ve altyapı gibi gelir getirecek alanlar yerine bütçe açıklarına harcandı; bu da iflasa (1875) yol açtı.'),
  ('17. yüzyılda bir mültezim, üç yıllığına bir mukataayı 90.000 akçeye almıştır. Bu kişinin zarar etmemesi için yıllık ortalama en az ne kadar vergi toplaması gerekir?', '30.000 akçe', ['45.000 akçe', '90.000 akçe', '15.000 akçe'], '90.000 akçelik bedel üç yıla bölündüğünde yıllık 30.000 akçe eder; mültezim kâr için bundan fazlasını toplamaya çalışırdı.'),
  ('Osmanlı ile Memlükler arasındaki ilk silahlı mücadele hangi padişah döneminde yaşanmıştır?', 'II. Bayezid', ['Yavuz Sultan Selim', 'Fatih Sultan Mehmed', 'II. Murad'], '1485-1491 Osmanlı-Memlük Savaşı II. Bayezid döneminde yaşandı ve kesin bir sonuç alınamadan barışla bitti.'),
  ('19. yüzyılda Osmanlı\'da demiryolu imtiyazlarının çoğunlukla yabancı şirketlere verilmesinin sonucu hangisidir?', 'Hatların daha çok hammadde taşıma ve yabancı çıkarlara göre şekillenmesi', ['Osmanlı\'nın demiryolu sanayisinde öncü olması', 'Demiryollarının yalnız askerî amaçla kullanılması', 'Yabancı şirketlerin Osmanlı\'ya vergi ödemesinin yasaklanması'], 'Hatlar genellikle limanlara ürün taşıyacak biçimde planlandı; kilometre garantisi gibi ödemeler de hazineye yük oldu.'),
  ('19. yüzyılda Osmanlı\'da fabrikalar (Feshane, Hereke, Zeytinburnu) açılmasına rağmen sanayileşmenin sınırlı kalması en çok neyle açıklanır?', 'Serbest ticaret antlaşmaları nedeniyle ucuz Avrupa mallarıyla rekabet edilememesi', ['Osmanlı\'da hiç hammadde bulunmaması', 'Halkın fabrika ürünlerini satın almaktan yasaklanması', 'Fabrikaların yalnız Avrupa\'ya mal üretmesi'], 'Düşük gümrük vergileri yerli fabrikaları korumasız bıraktı; sermaye ve teknik eleman eksikliği de etkiliydi.'),
  ('Bab-ı Âli Baskını\'ndan kısa süre sonra 1913\'te suikasta kurban giden sadrazam kimdir?', 'Mahmud Şevket Paşa', ['Kâmil Paşa', 'Said Halim Paşa', 'Talat Paşa'], 'Mahmud Şevket Paşa Haziran 1913\'te bir suikastla öldürüldü; ardından İttihatçılar muhalefeti tasfiye etti.'),
  ('Osmanlı\'nın I. Dünya Savaşı\'nda birçok cephede savaşmak zorunda kalmasının, savaşın sonucuna etkisi en iyi nasıl değerlendirilir?', 'Sınırlı insan ve kaynağın dağılması uzun vadede yenilgiyi hızlandırmıştır', ['Cephe sayısının fazlalığı Osmanlı\'ya üstünlük sağlamıştır', 'Osmanlı yalnız tek bir cephede savaştığı için kayıp vermemiştir', 'Cephelerin çokluğu savaşın kısa sürmesini sağlamıştır'], 'Kafkasya, Çanakkale, Irak, Suriye-Filistin, Hicaz ve diğer cepheler Osmanlı\'nın kaynaklarını tüketti.'),
];
